//! Borrowed original static-reference DATA over existing native owners.
use dm_ir::{PackedU128,Resolver,SymbolId,ResolveQuery as Q,ResolvedMeaning as M,ProcedureDefinition};
use dm_tree::{SemanticTree,MemberKind,DefinitionMode};
use crate::checker_expression_visit::OriginalValue;
#[derive(Clone,Copy)]pub(crate) enum Failure<'a>{NoValue,NonPath(OriginalValue<'a>),MissingType(OriginalValue<'a>),MissingField(SymbolId),MissingProc(SymbolId)}
pub(crate) fn declaration_kind_using<E:From<String>+From<&'static str>>(tree:&SemanticTree,resolver:&(impl Resolver+?Sized),profile:PackedU128,owner:SymbolId,name:SymbolId,poll:&mut impl FnMut()->Result<(),E>)->Result<Option<&'static str>,E>{
 poll()?;tree.validate_checker_builtin_profile(profile).map_err(|e|format!("static reference profile: {e:?}"))?;let catalog=dm_tree::checker_builtins::pinned_catalog().map_err(|e|format!("static reference catalog: {e:?}"))?;if catalog.profile!=profile{return Err("static reference catalog profile differs".into())}
 let query=Q::Ancestry(owner);let actual=Resolver::resolve(tree,query);if resolver.resolve(query)!=actual{return Err("static reference ancestry differs".into())}let M::Symbols(ancestors)=actual else{return Err("static reference ancestry absent".into())};
 for owner in ancestors.iter().copied(){poll()?;let mut kind=None;for verb in[false,true]{poll()?;let query=Q::SourceDeclarationChain{owner,name,verb};let actual=Resolver::resolve(tree,query);if resolver.resolve(query)!=actual{return Err("static reference source declaration differs".into())}let rows=match actual{M::Missing=>continue,M::Members(rows)=>rows,_=>return Err("static reference source declaration chain absent".into())};for row in rows.iter(){poll()?;let M::Declaration{identity,definition,..}=row else{return Err("static reference declaration row malformed".into())};if identity.owner==owner&&*definition==ProcedureDefinition::Declare{let next=if identity.verb{"verb"}else{"proc"};if kind.replace(next).is_some(){return Err("static reference multiple original declaration slots are not issued".into())}break}}}
  for row in catalog.declarations.iter(){poll()?;if row.owner==owner&&row.name==name&&row.definition==DefinitionMode::Declare&&matches!(row.kind,MemberKind::Proc|MemberKind::Verb){let next=if row.kind==MemberKind::Verb{"verb"}else{"proc"};if kind.replace(next).is_some(){return Err("static reference duplicate source/builtin declaration slot is not issued".into())}}}if kind.is_some(){return Ok(kind)}
 }Ok(None)
}

pub(crate) fn prefab_type_using<E:From<String>+From<&'static str>>(tree:&SemanticTree,resolver:&(impl Resolver+?Sized),value:OriginalValue<'_>,poll:&mut impl FnMut()->Result<(),E>)->Result<Option<SymbolId>,E>{
 poll()?;let selected=match value{OriginalValue::PrefabOwner(owner)=>Some(owner),OriginalValue::PrefabPath(path)=>tree.lookup_type(SymbolId::of(path)).and_then(|id|tree.type_node(id)).filter(|row|tree.symbols().text(row.path)==Some(path)).map(|row|row.path),OriginalValue::ProcedurePath{owner,kind,name}=>{let prefix=tree.symbols().text(owner).ok_or("static reference prefab owner spelling absent")?;let mut found=None;for row in tree.types(){poll()?;let path=tree.symbols().text(row.path).ok_or("static reference type spelling absent")?;let expected=prefix.split('/').filter(|p|!p.is_empty()).chain(kind).chain(std::iter::once(name));if path.split('/').filter(|p|!p.is_empty()).eq(expected){if found.replace(row.path).is_some(){return Err("static reference prefab type duplicated".into())}}}found},_=>return Err("non-path value passed to static prefab resolver".into())};
 if let Some(id)=selected{let query=Q::Type(id);let actual=Resolver::resolve(tree,query);if actual!=M::Symbol(id)||resolver.resolve(query)!=actual{return Err("static reference type differs from current native resolver".into())}}poll()?;Ok(selected)
}
